using DSWI_T1_1.Dtos;using DSWI_T1_1.Services.Interfaces;using Microsoft.AspNetCore.Mvc;namespace DSWI_T1_1.Controllers;public class PacientesController:Controller{private readonly IPacienteService s;public PacientesController(IPacienteService x)=>s=x;public async Task<IActionResult> Index()=>View(await s.ObtenerTodosAsync());[HttpGet]public IActionResult Create()=>View(new PacienteDto());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Create(PacienteDto d){if(!ModelState.IsValid)return View(d);await s.CrearAsync(d);TempData["Mensaje"]="Paciente registrado.";return RedirectToAction(nameof(Index));}[HttpGet]public async Task<IActionResult> Edit(int id){var d=await s.ObtenerPorIdAsync(id);return d==null?NotFound():View(d);}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Edit(PacienteDto d){if(!ModelState.IsValid)return View(d);if(!await s.EditarAsync(d))return NotFound();TempData["Mensaje"]="Paciente actualizado.";return RedirectToAction(nameof(Index));}}